test('primary withdrawal during postcommit pins read blocks dispatch, intent and reservation responses',async()=>{
 for(const operation of ['startInstallationWrite','readInstallationIntent','beginInstallation','read','reserve']){
  let active=false,calls=0,release,reached;const f=await fixture(),{createPrivateQaProvisioning}=await load(),original=createPrivateQaProvisioning(f.options);await original.reserve(f.creationRef);const intent=await original.beginInstallation(f.creationRef);const blocked=new Promise(resolve=>{reached=resolve;});const actor=createPrivateQaProvisioning({...f.options,readPins:async()=>{if(active&&++calls===3){reached();await new Promise(resolve=>{release=resolve;});}return structuredClone(f.pins);}});
  // reserve has additional in-transaction pin reads; trigger its final source
  // via the tx ACK rather than a guessed read count.
  let committed=false;const wrapped={...f.storage,transaction:async work=>{const result=await f.storage.transaction(work);committed=true;return result;}};
  const finalActor=operation==='reserve'?createPrivateQaProvisioning({...f.options,storage:wrapped,readPins:async()=>{if(committed){committed=false;reached();await new Promise(resolve=>{release=resolve;});}return structuredClone(f.pins);}}):actor;
  active=true;const pending=operation==='startInstallationWrite'?finalActor[operation](f.creationRef,intent.intentId,1):finalActor[operation](f.creationRef);await blocked;assert.equal(await original.withdraw(f.creationRef,1),true);release();assert.equal(await pending,null,operation);assert.equal((await original.installationHistory(f.creationRef)).state,'withdrawn');
 }
});
