function storage({afterCommit,onPut}={}){let values=new Map(),queue=Promise.resolve();return {get:async key=>structuredClone(values.get(key)),transaction(fn){const run=queue.then(async()=>{const next=new Map(values);const result=await fn({get:async key=>structuredClone(next.get(key)),put:async(key,value)=>{next.set(key,structuredClone(value));if(onPut)await onPut(key);}});values=next;if(afterCommit)await afterCommit();return result;});queue=run.catch(()=>{});return run;}};}
